SELECT DATE_FORMAT(observed_at, '%Y-%m-%d %H:%i') AS minute_ksa, COUNT(*) AS stalled_events, MAX(TIMESTAMPDIFF(MICROSECOND, observed_at, created_at)) / 1000 AS max_lag_ms FROM crypto_ai.market_price_event WHERE observed_at BETWEEN '2026-10-11 18:00:00' AND '2026-10-12 12:00:00' AND TIMESTAMPDIFF(MICROSECOND, observed_at, created_at) > 500000 GROUP BY minute_ksa ORDER BY minute_ksa LIMIT 200;